-- Listening limits of exercise audios, stored per student (the admin can give listenings back).
-- Run ONCE in Supabase → SQL Editor, BEFORE uploading the new files.
create table if not exists content."AudioPlays" (
    "Id"        integer generated by default as identity primary key,
    "AuthId"    text        not null,
    "AudioKey"  text        not null,
    "Count"     integer     not null default 0,
    "UpdatedAt" timestamptz not null default now()
);

create unique index if not exists "IX_AudioPlays_AuthId_AudioKey"
on content."AudioPlays" ("AuthId", "AudioKey");
